```cpp
#include <iostream>
#include <fstream>
#include <vector>
using namespace std;

int nwd(int a, int b) {
    while (b) {
        int t = b;
        b = a % b;
        a = t;
    }
    return a;
}

int main() {
    ifstream plik("ciag.txt");
    vector<int> tab;
    int n;
    while (plik >> n) tab.push_back(n);

    int ile = 0;
    cout << "a) Wzajemnie pierwsze z sasiadami:" << endl;
    for (int i = 0; i < (int)tab.size(); i++) {
        bool ok = true;
        if (i > 0 && nwd(tab[i], tab[i - 1]) != 1) ok = false;
        if (i < (int)tab.size() - 1 && nwd(tab[i], tab[i + 1]) != 1) ok = false;
        if (ok) {
            cout << "   pozycja " << i << ": " << tab[i] << endl;
            ile++;
        }
    }
    cout << "b) Znaleziono: " << ile << endl;
    return 0;
}
```

**Wyjasnienie**: Algorytm Euklidesa do obliczenia NWD. Dla kazdego elementu sprawdzamy, czy NWD z kazdym istniejacym sasiadem wynosi 1.

Weryfikacja (dane: [0]=12, [1]=8, [2]=15, [3]=10, [4]=9, [5]=14, [6]=11, [7]=6):
- [0]=12: prawy=8, NWD(12,8)=4 -> NIE
- [1]=8: lewy=12 NWD=4 -> NIE
- [2]=15: lewy=8 NWD=1, prawy=10 NWD=5 -> NIE
- [3]=10: lewy=15 NWD=5 -> NIE
- [4]=9: lewy=10 NWD=1, prawy=14 NWD=1 -> TAK
- [5]=14: lewy=9 NWD=1, prawy=11 NWD=1 -> TAK
- [6]=11: lewy=14 NWD=1, prawy=6 NWD=1 -> TAK
- [7]=6: lewy=11 NWD=1 -> TAK
- Razem: 4
